import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TS 64
#define TPTS 16
#define RT 4
// C = triu(A * B) where A, B are upper triangular N x N matrices.
// C[i][j] = sum_{k=i}^{j} A[i][k] * B[k][j] for j >= i, 0 otherwise.
// Only tiles on or above the diagonal do any multiply work; tiles strictly
// below the diagonal just write zeros. For an on/above-diagonal tile with
// block row bi and block col bj, the reduction only spans k-tiles [bi, bj]
// because A is zero left of the diagonal and B is zero below it.
//
// Asynchronous copy helpers (cp.async on sm_80+, synchronous fallback).
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ < 800)
__device__ __forceinline__ void cp_async16(void* smem_ptr, const void* gmem_ptr) {
    *reinterpret_cast<float4*>(smem_ptr) = *reinterpret_cast<const float4*>(gmem_ptr);
}
__device__ __forceinline__ void cp_async_commit() {}
__device__ __forceinline__ void cp_async_wait_one() {}
#else
__device__ __forceinline__ void cp_async16(void* smem_ptr, const void* gmem_ptr) {
    unsigned saddr = static_cast<unsigned>(__cvta_generic_to_shared(smem_ptr));
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(saddr), "l"(gmem_ptr));
}
__device__ __forceinline__ void cp_async_commit() {
    asm volatile("cp.async.commit_group;\n" ::);
}
__device__ __forceinline__ void cp_async_wait_one() {
    asm volatile("cp.async.wait_group 1;\n" ::);
}
#endif
// Optimization: 4x4 thread-level register tiling on 64x64 CTA tiles,
// with vectorized float4 global->shared staging when N % TS == 0.
// This doubles the arithmetic intensity per shared-memory byte compared
// to the previous 2x2-per-thread 32x32 tile version, relieving the
// shared-memory/issue pressure seen at ~95% compute throughput.
__global__ void __launch_bounds__(TPTS * TPTS, 2) triu_matmul_kernel(const float* __restrict__ A,
                                   const float* __restrict__ B,
                                   float* __restrict__ C,
                                   int N) {
    // Double-buffered dynamic shared memory: 2 stages x (As + Bs) tiles.
    extern __shared__ __align__(16) float dyn_smem[];
    typedef float SmemTile[TS][TS + 4];
    SmemTile* As = reinterpret_cast<SmemTile*>(dyn_smem);
    SmemTile* Bs = reinterpret_cast<SmemTile*>(dyn_smem + 2 * TS * (TS + 4));
    const int blockRow = blockIdx.y;
    const int blockCol = blockIdx.x;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    // Tiles strictly below the diagonal: result is all zeros.
    if (blockCol < blockRow) {
        #pragma unroll
        for (int i = 0; i < RT; ++i) {
            #pragma unroll
            for (int j = 0; j < RT; ++j) {
                int r = blockRow * TS + ty + i * TPTS;
                int c = blockCol * TS + tx + j * TPTS;
                if (r < N && c < N) C[r * N + c] = 0.0f;
            }
        }
        return;
    }
    float acc[RT][RT] = {};
    // N % TS == 0 guarantees 16B-aligned float4 accesses and fully
    // in-bounds tiles, enabling the cp.async two-stage pipeline that
    // overlaps global-memory staging of tile kt+1 with compute on tile kt.
    // This hides global latency at the low (smem-limited) occupancy.
    const bool aligned = (N % TS) == 0;
    if (aligned) {
        // Stage loader: each thread stages 4 rows x float4 per operand.
        auto load_stage = [&](int kt, int buf) {
            #pragma unroll
            for (int i = 0; i < RT; ++i) {
                int ar = blockRow * TS + ty + i * TPTS;
                int ac = kt * TS + tx * RT;
                cp_async16(&As[buf][ty + i * TPTS][tx * RT], A + ar * N + ac);
                int br = kt * TS + ty + i * TPTS;
                int bc = blockCol * TS + tx * RT;
                cp_async16(&Bs[buf][ty + i * TPTS][tx * RT], B + br * N + bc);
            }
        };
        load_stage(blockRow, 0);
        cp_async_commit();
        int buf = 0;
        for (int kt = blockRow; kt <= blockCol; ++kt) {
            if (kt < blockCol) load_stage(kt + 1, buf ^ 1);
            cp_async_commit();
            cp_async_wait_one();
            __syncthreads();
            #pragma unroll
            for (int k = 0; k < TS; ++k) {
                float a[RT], b[RT];
                #pragma unroll
                for (int i = 0; i < RT; ++i) a[i] = As[buf][ty + i * TPTS][k];
                #pragma unroll
                for (int j = 0; j < RT; ++j) b[j] = Bs[buf][k][tx + j * TPTS];
                #pragma unroll
                for (int i = 0; i < RT; ++i) {
                    #pragma unroll
                    for (int j = 0; j < RT; ++j) {
                        acc[i][j] += a[i] * b[j];
                    }
                }
            }
            __syncthreads();
            buf ^= 1;
        }
    } else {
        for (int kt = blockRow; kt <= blockCol; ++kt) {
            #pragma unroll
            for (int i = 0; i < RT; ++i) {
                #pragma unroll
                for (int j = 0; j < RT; ++j) {
                    int ar = blockRow * TS + ty + i * TPTS;
                    int ac = kt * TS + tx + j * TPTS;
                    As[0][ty + i * TPTS][tx + j * TPTS] =
                        (ar < N && ac < N) ? A[ar * N + ac] : 0.0f;
                    int br = kt * TS + ty + i * TPTS;
                    int bc = blockCol * TS + tx + j * TPTS;
                    Bs[0][ty + i * TPTS][tx + j * TPTS] =
                        (br < N && bc < N) ? B[br * N + bc] : 0.0f;
                }
            }
            __syncthreads();
            #pragma unroll
            for (int k = 0; k < TS; ++k) {
                float a[RT], b[RT];
                #pragma unroll
                for (int i = 0; i < RT; ++i) a[i] = As[0][ty + i * TPTS][k];
                #pragma unroll
                for (int j = 0; j < RT; ++j) b[j] = Bs[0][k][tx + j * TPTS];
                #pragma unroll
                for (int i = 0; i < RT; ++i) {
                    #pragma unroll
                    for (int j = 0; j < RT; ++j) {
                        acc[i][j] += a[i] * b[j];
                    }
                }
            }
            __syncthreads();
        }
    }
    #pragma unroll
    for (int i = 0; i < RT; ++i) {
        #pragma unroll
        for (int j = 0; j < RT; ++j) {
            int r = blockRow * TS + ty + i * TPTS;
            int c = blockCol * TS + tx + j * TPTS;
            if (r < N && c < N) {
                C[r * N + c] = (c >= r) ? acc[i][j] : 0.0f;
            }
        }
    }
}
torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D");
    TORCH_CHECK(A.size(0) == A.size(1) && B.size(0) == B.size(1) &&
                A.size(0) == B.size(0), "Inputs must be square and same size");
    const int N = A.size(0);
    auto C = torch::empty_like(A);
    dim3 block(TPTS, TPTS);
    dim3 grid((N + TS - 1) / TS, (N + TS - 1) / TS);
    const int smemBytes = 4 * TS * (TS + 4) * sizeof(float);
    static int configured_smem = 0;
    if (configured_smem != smemBytes) {
        cudaFuncSetAttribute(triu_matmul_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize, smemBytes);
        configured_smem = smemBytes;
    }
    triu_matmul_kernel<<<grid, block, smemBytes>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);
    return C;
}
"""

cpp_src = "torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B);"

_ext = load_inline(
    name="triu_matmul_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["triu_matmul"],
    extra_cuda_cflags=["-O3", "--ptxas-options=-O3", "-maxrregcount=56"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        return _ext.triu_matmul(A.contiguous(), B.contiguous())

